                }}
                export -f nc

                date() {{
                    echo "1741054377"
                }}
            """
        )
        aliases_fp.close()
        nc_fp.close()

        bash_run(
            "log_recent_bot_traffic stats.ol-covers0.bot_traffic openlibrary-covers_nginx-1",
            sources=[aliases_fp.name, "utils.sh"],
        )

        with open(nc_fp.name) as f:
            expected_output = """
